import { Injectable } from '@angular/core';
import { Verse } from '../../common/verse/verse';

// Image sizes supported (kept for backward compatibility with existing images)
// All new images are now square
type ImageSize = 'square' | 'iphone' | 'desktop';

interface ProcessedVerse {
  number: number;
  text: string;
}

interface ProcessedVerseImage {
  quote: string;
  source: string;
}

@Injectable({
  providedIn: 'root',
})
export class VerseQuoteFactory {
  private readonly wordLimits: Record<ImageSize, number> = {
    square: 40,
    iphone: 70,
    desktop: 70,
  };

  create(verse: Verse, size: ImageSize): ProcessedVerseImage {
    if (!verse.content) {
      throw new Error('Verse content is empty');
    }

    const verseTexts = this.splitIntoVerses(verse);
    const includedVerses = this.truncateToWordLimit(verseTexts, size);

    return {
      quote: this.createQuote(includedVerses),
      source: this.createSource(verse, includedVerses),
    };
  }

  private splitIntoVerses(verse: Verse): ProcessedVerse[] {
    return verse
      .content!.split(/(?=<sup>\s*\d+\s*<\/sup>)/)
      .map((v) => ({
        number: parseInt(v.match(/<sup>\s*(\d+)\s*<\/sup>/)?.[1] || '0'),
        text: v.replace(/<sup>\s*\d+\s*<\/sup>/g, '').trim(),
      }))
      .filter(
        (v) =>
          v.number >= (verse.start_verse ?? 0) &&
          v.number <= (verse.end_verse ?? 0)
      );
  }

  private truncateToWordLimit(
    verses: ProcessedVerse[],
    size: ImageSize
  ): ProcessedVerse[] {
    const wordLimit = this.wordLimits[size];
    let totalWords = 0;
    let includedVerses: ProcessedVerse[] = [];

    // Add verses until we hit the word limit
    for (const verse of verses) {
      const words = verse.text.split(/\s+/);
      if (totalWords + words.length <= wordLimit) {
        includedVerses.push(verse);
        totalWords += words.length;
      } else if (includedVerses.length === 0) {
        // If we haven't included any verses yet, take words from this verse
        includedVerses = [
          {
            number: verse.number,
            text: words.slice(0, wordLimit).join(' ') + '...',
          },
        ];
        break;
      } else {
        break;
      }
    }

    return includedVerses;
  }

  private createQuote(verses: ProcessedVerse[]): string {
    return verses.map((v) => v.text).join(' ');
  }

  private createSource(verse: Verse, includedVerses: ProcessedVerse[]): string {
    const lastIncludedVerse =
      includedVerses[includedVerses.length - 1]?.number || verse.start_verse;
    return verse.start_verse === lastIncludedVerse
      ? `${verse.book} ${verse.chapter}:${verse.start_verse}`
      : `${verse.book} ${verse.chapter}:${verse.start_verse}-${lastIncludedVerse}`;
  }
}
