import { Component, Input, OnDestroy, OnInit, inject, signal } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import {
  IonButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonIcon,
  IonTitle,
  IonToolbar,
  ModalController,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { chevronBack, shareOutline } from 'ionicons/icons';
import { AlertService } from 'src/app/common/alert/alert.service';
import { NavigatorService } from 'src/app/common/navigator/navigator.service';
import { StorageService } from 'src/app/common/storage/storage.service';

@Component({
    selector: 'app-image-modal',
    templateUrl: './image-modal.component.html',
    styleUrls: ['./image-modal.component.scss'],
    imports: [
        IonHeader,
        IonToolbar,
        IonTitle,
        IonButtons,
        IonButton,
        IonContent,
        IonIcon,
    ]
})
export class ImageModalComponent implements OnInit, OnDestroy {
  @Input({ required: true }) imagePath!: string;

  private alertService = inject(AlertService);
  private modalCtrl = inject(ModalController);
  private navigatorService = inject(NavigatorService);
  private sanitizer = inject(DomSanitizer);
  private storageService = inject(StorageService);

  imageUrl = signal<SafeUrl | null>(null);
  private blobUrl: string | null = null;

  constructor() {
    addIcons({ chevronBack, shareOutline });
  }

  async ngOnInit() {
    await this.loadImage();
  }

  ngOnDestroy() {
    if (this.blobUrl) {
      URL.revokeObjectURL(this.blobUrl);
    }
  }

  async dismiss() {
    await this.modalCtrl.dismiss();
  }

  async shareImage() {
    if (!this.blobUrl) {
      return;
    }

    try {
      const response = await fetch(this.blobUrl);
      const blob = await response.blob();
      const file = await this.navigatorService.createFileFromBlob(
        blob,
        'verse-image.png',
        'image/png'
      );

      // Leave a space at the end so the user picker doesn't show
      await this.navigatorService.shareFile(
        file,
        'Image created by @heybibleapp '
      );
    } catch (error: unknown) {
      if (error instanceof Error && error.name === 'AbortError') {
        return;
      }

      await this.alertService.createNotice({
        message: 'Failed to share image',
        duration: 5000,
        positionAnchor: 'footer',
        color: 'danger',
      });
    }
  }

  private async loadImage() {
    try {
      const blob = await this.storageService.download('images', this.imagePath);
      this.blobUrl = URL.createObjectURL(blob);
      this.imageUrl.set(this.sanitizer.bypassSecurityTrustUrl(this.blobUrl));
    } catch (error) {
      await this.alertService.createNotice({
        message: 'Failed to load image',
        duration: 5000,
        positionAnchor: 'footer',
        color: 'danger',
      });
    }
  }
}
