import { Injectable, inject } from '@angular/core';
import { Storage } from '@ionic/storage-angular';
import { LoggingService } from '../logging/logging.service';

export interface CachedImage {
  imagePath: string;
  blob: Blob;
  cachedAt: number;
  expiresAt: number;
}

@Injectable({
  providedIn: 'root',
})
export class ImageCacheService {
  private readonly CACHE_DURATION = 7 * 24 * 60 * 60 * 1000; // 7 days in milliseconds
  private readonly CACHE_PREFIX = 'image_cache_';

  private storage = inject(Storage);
  private loggingService = inject(LoggingService);

  async getCachedImage(imagePath: string): Promise<Blob | null> {
    try {
      const cacheKey = this.getCacheKey(imagePath);

      const cachedData = (await this.storage.get(cacheKey)) as CachedImage | null;

      if (!cachedData) {
        return null;
      }

      // Check if cache has expired and remove it if so
      if (Date.now() > cachedData.expiresAt) {
        await this.storage.remove(cacheKey);
        return null;
      }

      // Return the blob, handling both Blob instances and serialized data
      if (cachedData.blob instanceof Blob) {
        return cachedData.blob;
      }

      return new Blob([cachedData.blob]);
    } catch (error) {
      this.loggingService.error('Error getting cached image:', error);
      return null;
    }
  }

  async setCachedImage(imagePath: string, blob: Blob): Promise<void> {
    try {
      const cacheKey = this.getCacheKey(imagePath);

      // Convert blob to array buffer for better storage compatibility
      const arrayBuffer = await blob.arrayBuffer();

      const cachedImage: CachedImage = {
        imagePath,
        blob: new Blob([arrayBuffer], { type: blob.type }),
        cachedAt: Date.now(),
        expiresAt: Date.now() + this.CACHE_DURATION,
      };

      await this.storage.set(cacheKey, cachedImage);
    } catch (error) {
      this.loggingService.error('Error caching image:', error);
      throw error;
    }
  }

  async removeCachedImage(imagePath: string): Promise<void> {
    try {
      const cacheKey = this.getCacheKey(imagePath);
      await this.storage.remove(cacheKey);
    } catch (error) {
      this.loggingService.error('Error removing cached image:', error);
      throw error;
    }
  }

  private getCacheKey(imagePath: string): string {
    return `${this.CACHE_PREFIX}${imagePath}`;
  }
}
