import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { AlertService } from '../common/alert/alert.service';
import { Image, Verse } from '../common/verse/verse';
import { LoadingService } from '../common/loading/loading.service';
import { ImageTheme } from 'supabase/functions/images/themes';
import {
  VeniceImageModel,
  VENICE_IMAGE_MODELS,
  DEFAULT_VENICE_MODEL,
} from 'supabase/functions/venice/models';

@Injectable({
  providedIn: 'root',
})
export class ImagesService {
  private readonly alertService = inject(AlertService);
  private readonly loadingService = inject(LoadingService);
  private readonly supabase = inject<SupabaseClient<Database>>(SupabaseClient);


  async getImagesWithVerse() {
    try {
      const { data, error } = await this.supabase
        .from('images')
        .select('*, verse:verses(*)')
        .order('id', { ascending: false });

      if (error) {
        throw error;
      }

      return data as ImageWithVerse[];
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to fetch images',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
      return [];
    }
  }

  async deleteImage(id: number, storagePath: string) {
    try {
      this.loadingService.setLoading(true);

      // First delete the file from storage
      const { error: storageError } = await this.supabase.storage
        .from('images')
        .remove([storagePath]);

      if (storageError) {
        throw new Error(`Failed to delete image file: ${storageError.message}`);
      }

      // Then delete the database record
      const { error: dbError } = await this.supabase
        .from('images')
        .delete()
        .eq('id', id);

      if (dbError) {
        throw new Error(`Failed to delete image record: ${dbError.message}`);
      }
    } catch (error) {
      this.alertService.createNotice({
        message: 'Failed to delete image',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  async generateImage(
    verse_id: number,
    quote: string,
    source: string,
    theme: ImageTheme,
    veniceModel?: VeniceImageModel
  ): Promise<ImageGenerationResponse> {
    const { data, error } = await this.supabase.functions.invoke<ImageGenerationResponse>('venice', {
      body: {
        verse_id,
        quote,
        source,
        theme,
        model: veniceModel ?? DEFAULT_VENICE_MODEL,
      },
    });

    if (error) {
      throw new Error(`Failed to generate image: ${error.message}`);
    }

    if (!data) {
      throw new Error('No data returned from image generation');
    }

    return data;
  }

  getVeniceModels() {
    return VENICE_IMAGE_MODELS;
  }

  getDefaultVeniceModel() {
    return DEFAULT_VENICE_MODEL;
  }
}

interface ImageGenerationResponse {
  path: string;
  verse_id: number;
  created_at: string;
  prompt?: string;
  size?: string;
  model?: string;
}

export type ImageWithVerse = Image & {
  verse: Verse;
};

// Re-export Venice types for component usage
export type { VeniceImageModel } from 'supabase/functions/venice/models';
export {
  VENICE_IMAGE_MODELS,
  DEFAULT_VENICE_MODEL,
  LEGACY_MODEL_MAP,
  resolveModel,
  getModelInfo,
} from 'supabase/functions/venice/models';
