import { Component, Input, OnDestroy, inject } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { AsyncPipe } from '@angular/common';
import { IonSpinner, ModalController } from '@ionic/angular/standalone';
import { BehaviorSubject, Observable, of, from } from 'rxjs';
import {
  switchMap,
  distinctUntilChanged,
  map,
  catchError,
  mergeMap,
} from 'rxjs/operators';
import { AlertService } from 'src/app/common/alert/alert.service';
import { StorageService } from 'src/app/common/storage/storage.service';
import { ImageCacheService } from 'src/app/common/storage/image-cache.service';
import { LoggingService } from 'src/app/common/logging/logging.service';
import { WindowService } from 'src/app/common/window/window.service';
import { ImageModalComponent } from './image-modal/image-modal.component';

@Component({
    selector: 'app-image-content',
    templateUrl: './image-content.component.html',
    styleUrls: ['./image-content.component.scss'],
    imports: [IonSpinner, AsyncPipe]
})
export class ImageContentComponent implements OnDestroy {
  private readonly imagePathSubject = new BehaviorSubject<string>('');
  private readonly alertService = inject(AlertService);
  private readonly modalCtrl = inject(ModalController);
  private readonly sanitizer = inject(DomSanitizer);
  private readonly storageService = inject(StorageService);
  private readonly imageCacheService = inject(ImageCacheService);
  private readonly loggingService = inject(LoggingService);
  private readonly windowService = inject(WindowService);

  private activeBlobUrls = new Set<string>();

  @Input({ required: true })
  set imagePath(value: string) {
    this.imagePathSubject.next(value);
  }

  get imagePath(): string {
    return this.imagePathSubject.value;
  }

  readonly imageUrl$: Observable<SafeUrl | null> = this.imagePathSubject.pipe(
    distinctUntilChanged(),
    switchMap((imagePath) => {
      if (!imagePath) {
        return of(null);
      }

      return this.loadImageStream(imagePath).pipe(
        catchError((error) => {
          this.loggingService.error('Failed to load image:', error);
          this.alertService.createNotice({
            message: 'Failed to load image',
            duration: 5000,
            positionAnchor: 'footer',
            color: 'danger',
          });
          return of(null);
        })
      );
    })
  );

  ngOnDestroy() {
    this.cleanupAllBlobUrls();
  }

  async openModal(event: MouseEvent) {
    event.preventDefault();
    event.stopPropagation();
    
    // Use larger modal on tablet and desktop devices
    const window = this.windowService.getWindow();
    const isLargeScreen = window.innerWidth >= 768;
    
    const modal = await this.modalCtrl.create({
      component: ImageModalComponent,
      componentProps: {
        imagePath: this.imagePath,
      },
      breakpoints: isLargeScreen ? [0, 1] : undefined,
      initialBreakpoint: isLargeScreen ? 1 : undefined,
      cssClass: isLargeScreen ? 'large-image-modal' : '',
    });

    await modal.present();
  }

  private loadImageStream(imagePath: string): Observable<SafeUrl> {
    this.loggingService.log(`Loading image: ${imagePath}`);

    return from(this.imageCacheService.getCachedImage(imagePath)).pipe(
      mergeMap((cachedBlob) => {
        if (cachedBlob) {
          this.loggingService.log(`Loading image from cache: ${imagePath}`);
          return of(cachedBlob);
        }
        
        this.loggingService.log(`Downloading image: ${imagePath}`);
        return from(this.storageService.download('images', imagePath)).pipe(
          map((blob) => {
            // Cache the downloaded image for future use (fire and forget)
            this.imageCacheService
              .setCachedImage(imagePath, blob)
              .catch((cacheError) => {
                this.loggingService.warn('Failed to cache image:', cacheError);
              });
            this.loggingService.log(`Cached image: ${imagePath}`);
            return blob;
          })
        );
      }),
      map((blob) => this.createImageUrl(blob))
    );
  }

  private createImageUrl(blob: Blob): SafeUrl {
    const blobUrl = URL.createObjectURL(blob);
    this.activeBlobUrls.add(blobUrl);
    return this.sanitizer.bypassSecurityTrustUrl(blobUrl);
  }

  private cleanupAllBlobUrls() {
    this.activeBlobUrls.forEach((url) => {
      URL.revokeObjectURL(url);
    });
    this.activeBlobUrls.clear();
  }
}
