import { CommonModule, DatePipe } from '@angular/common';
import { Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { RouterLink } from '@angular/router';
import {
  IonButton,
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardSubtitle,
  IonCardTitle,
  IonIcon,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { refreshOutline } from 'ionicons/icons';
import { AlertService } from 'src/app/common/alert/alert.service';
import { Attachment, ImageAttachment } from '../attachment';
import { ImageContentComponent } from '../image-content/image-content.component';

@Component({
    selector: 'app-image-attachment-card',
    templateUrl: './image-attachment-card.component.html',
    styleUrls: ['./image-attachment-card.component.scss'],
    imports: [
        CommonModule,
        IonCardSubtitle,
        IonCardTitle,
        IonCardHeader,
        IonCard,
        IonCardContent,
        IonIcon,
        IonButton,
        DatePipe,
        ImageContentComponent,
        RouterLink,
    ]
})
export class ImageAttachmentCardComponent {
  @Input({ required: true }) attachment!: ImageAttachment;
  @Input() routerLink: string[] | undefined = undefined;
  @Input() title = 'Attachment';

  @Output() remove = new EventEmitter<Attachment>();
  @Output() regenerate = new EventEmitter<ImageAttachment>();

  private alertService = inject(AlertService);

  closeIcon = 'node_modules/openmoji/color/svg/E24E.svg'; // ⏹️ Close Button

  async removeAttachment(event: MouseEvent) {
    event.stopPropagation();
    event.preventDefault();
    await this.alertService.presentAlert({
      header: 'Remove Attachment',
      message: 'Are you sure you want to remove this attachment?',
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
        },
        {
          text: 'Yes',
          handler: () => {
            this.remove.emit(this.attachment);
          },
        },
      ],
    });
  }

  regenerateImage(event: MouseEvent) {
    event.stopPropagation();
    event.preventDefault();
    this.regenerate.emit(this.attachment);
  }

  constructor() {
    addIcons({ refreshOutline });
  }
}
