// Default to a balanced quality/cost model
export const DEFAULT_VENICE_MODEL: VeniceImageModel = 'seedream-v4';

// Map legacy provider names to Venice equivalents
// Used for regenerating images created with old /images endpoint
export const LEGACY_MODEL_MAP: Record<string, VeniceImageModel> = {
  'openai': 'gpt-image-1-5',    // dall-e-3 → closest Venice equivalent
  'veniceai': 'hidream',         // same model, still available on Venice
  'xai': 'flux-2-pro',           // grok-2-image → no direct equivalent, use high-quality model
};

export function getModelInfo(model: VeniceImageModel): VeniceModelInfo {
  return VENICE_IMAGE_MODELS.find((m) => m.id === model)!;
}

/**
 * Resolves a stored model string to a valid Venice model.
 * Handles both new format (venice:model-name) and legacy format (provider-name).
 * Returns the model and whether a fallback was used.
 */
export function resolveModel(storedModel: string | null | undefined): {
  model: VeniceImageModel;
  wasRemapped: boolean;
  originalProvider?: string;
} {
  if (!storedModel) {
    return { model: DEFAULT_VENICE_MODEL, wasRemapped: false };
  }

  // New format: venice:model-name
  if (storedModel.startsWith('venice:')) {
    const modelName = storedModel.replace('venice:', '') as VeniceImageModel;
    // Verify it's still a valid model
    if (VENICE_IMAGE_MODELS.some(m => m.id === modelName)) {
      return { model: modelName, wasRemapped: false };
    }
    // Model was removed, fall back to default
    return { model: DEFAULT_VENICE_MODEL, wasRemapped: true, originalProvider: storedModel };
  }

  // Legacy format: provider name only
  if (storedModel in LEGACY_MODEL_MAP) {
    return {
      model: LEGACY_MODEL_MAP[storedModel],
      wasRemapped: true,
      originalProvider: storedModel,
    };
  }

  // Unknown format, use default
  return { model: DEFAULT_VENICE_MODEL, wasRemapped: true, originalProvider: storedModel };
}
