export enum ImageThemeType {
  Animals = 'animals',
  Celestial = 'celestial',
  Custom = 'custom',
  Fantasy = 'fantasy',
  Flowers = 'flowers',
  Landscape = 'landscape',
  Literal = 'literal',
  Medieval = 'medieval',
  Minimalist = 'minimalist',
  StainedGlass = 'stained_glass',
  Watercolor = 'watercolor',
}

export interface ImageTheme {
  type: ImageThemeType;
  content?: string;
}

export type ImageThemeWithContent = Required<ImageTheme>;

type ImageThemeFactoryType = Exclude<ImageThemeType, ImageThemeType.Custom>;
export function hasImageThemeFactory(
  themeType: ImageThemeType
): themeType is ImageThemeFactoryType {
  return themeType !== ImageThemeType.Custom;
}

export const imageThemeFactoryProvider: {
  [key in ImageThemeFactoryType]: (verse: string) => ImageThemeWithContent;
} = {
  [ImageThemeType.Animals]: createAnimalsThemePrompt,
  [ImageThemeType.Celestial]: createCelestialThemePrompt,
  [ImageThemeType.Fantasy]: createFantasyThemePrompt,
  [ImageThemeType.Flowers]: createFlowersThemePrompt,
  [ImageThemeType.Landscape]: createLandscapeThemePrompt,
  [ImageThemeType.Literal]: createLiteralThemePrompt,
  [ImageThemeType.Medieval]: createMedievalThemePrompt,
  [ImageThemeType.Minimalist]: createMinimalistThemePrompt,
  [ImageThemeType.StainedGlass]: createStainedGlassThemePrompt,
  [ImageThemeType.Watercolor]: createWatercolorThemePrompt,
};

function createAnimalsThemePrompt(verse: string) {
  return {
    type: ImageThemeType.Animals,
    content: `Create a delightful and imaginative image inspired by this Bible verse: "${verse}".
    Focus on animals in a natural setting, such as forests, grasslands, mountains, rivers, or other peaceful environments where animals might be found. Use vibrant yet natural colors and soft, inviting lighting to evoke a sense of wonder and harmony.
    The style should be realistic yet artistic, similar to charming wildlife photography or whimsical children's book illustrations.
    Please also avoid using any text in the image.`,
  };
}

