function createStainedGlassThemePrompt(verse: string) {
  return {
    type: ImageThemeType.StainedGlass,
    content: `Create a beautiful stained glass window design inspired by this Bible verse: "${verse}".
    Use rich, jewel-toned colors separated by dark lead lines in the traditional style of cathedral stained glass. The composition should feature geometric patterns and/or symbolic imagery that captures the essence of the verse in a reverent, glowing style.
    The image should have the luminous quality of light shining through colored glass, with the characteristic segmented appearance of stained glass artistry. 
    Focus on the decorative, mosaic-like quality of stained glass with its distinctive compartmentalized color areas and dark divisions between elements.
    Please avoid using any text in the image.`,
  };
}

function createWatercolorThemePrompt(verse: string) {
  return {
    type: ImageThemeType.Watercolor,
    content: `Create a delicate watercolor painting inspired by this Bible verse: "${verse}".
    Use soft, flowing colors with gentle blending and transparent washes that convey a dreamy, contemplative quality. The composition should feature light, airy elements with soft edges and subtle color transitions that reflect the emotion and meaning of the verse.
    The style should resemble traditional watercolor paintings with visible brush strokes, color bleeds, and the characteristic luminosity of watercolor pigments on paper.
    Avoid hard edges, bold lines, or heavy saturation. Instead, focus on the ethereal quality that watercolors naturally create.
    Please also avoid using any text in the image.`,
  };
}
